def rise_records(heights):
    lengths = []
    counts = []
    best = 0
    ways = 0
    for i in range(len(heights)):
        length = 1
        count = 1
        for j in range(i):
            if heights[j] < heights[i]:
                candidate = lengths[j] + 1
                if candidate > length:
                    length = candidate
                    count = counts[j]
                elif candidate == length:
                    count += counts[j]
        lengths.append(length)
        counts.append(count)
        if length > best:
            best = length
            ways = count
        elif length == best:
            ways += count
    return [best, ways]

